    const others = landing ? ctx.entitiesInRadius(landing, 2, { faction: 'enemy' }) : [];
    for (const oid of others) {
      if (!undead.includes(oid)) {
        ctx.damage(oid, Math.floor(baseDmg / 2), 'radiant');
        ctx.apply(oid, 'blind', 3);
      }
