}

function makeUndead(world, x = 3, y = 2) {
  const undead = world.create();
  world.add(undead, CreatureType, { type: "undead" });
  world.add(undead, Position, { x, y });
  world.add(undead, Vitality, { hp: 30, maxHp: 30 });
